    @m.app.middleware('http')
    async def _v137_html(request, call_next):
        response = await call_next(request)
        if request.url.path != '/' or getattr(response,'status_code',200) != 200:
            return response
        try:
            body=b''
            async for chunk in response.body_iterator:
                body+=chunk
            html=body.decode('utf-8',errors='replace')
            if 'v137-commercial-static-js' not in html:
                html=html.replace('</head>',parent_css+'</head>',1).replace('</body>',parent_js+'</body>',1)
            return HTMLResponse(html,status_code=response.status_code,headers={'Cache-Control':'no-store, no-cache, must-revalidate, max-age=0','Pragma':'no-cache','Expires':'0','X-Operations-UI-Version':'V137-COMMERCIAL-STATIC-DEMO'})
        except Exception as exc:
            print(f'[V137] HTML warning: {type(exc).__name__}: {exc}',flush=True)
            return response

    m._V137_COMMERCIAL_STATIC_DEMO=True
    print('[V137] Demo Comercial estático/interactivo instalado; sin pantalla en blanco.',flush=True)
